import { useEffect, useState } from 'react';
import { ClipboardList, Plus, Trash2 } from 'lucide-react';
import Alert from '../../../components/ui/Alert.jsx';
import Button from '../../../components/ui/Button.jsx';
import Drawer from '../../../components/ui/Drawer.jsx';
import Input from '../../../components/ui/Input.jsx';
import { createRequisition, updateRequisition } from '../../../services/requisitions.service.js';
import { listDrugs } from '../../../services/drugs.service.js';

let rowKey = 0;
const nextKey = () => {
  rowKey += 1;
    return rowKey;
    };

    const emptyRow = (drugId = '') => ({
      key: nextKey(),
        drugId,
          requestedQuantity: ''
          });

          export default function RequisitionFormDrawer({ open, onClose, onSaved, requisition }) {
            const isEditing = Boolean(requisition);
              const [drugs, setDrugs] = useState([]);
                const [rows, setRows] = useState([emptyRow()]);
                  const [notes, setNotes] = useState('');
                    const [error, setError] = useState('');
                      const [saving, setSaving] = useState(false);

                        useEffect(() => {
                            if (!open) {
                                  return;
                                      }
                                          setError('');
                                              setNotes(requisition?.notes || '');
                                                  setRows(
                                                        requisition && requisition.items?.length > 0
                                                                ? requisition.items.map((item) => ({
                                                                            key: nextKey(),
                                                                                        drugId: item.drugId,
                                                                                                    requestedQuantity: String(item.requestedQuantity)
                                                                                                              }))
                                                                                                                      : [emptyRow()]
                                                                                                                          );

                                                                                                                              listDrugs({ status: 'active', pageSize: 100 })
                                                                                                                                    .then((result) => setDrugs(result.items || []))
                                                                                                                                          .catch(() => setDrugs([]));
                                                                                                                                            }, [open, requisition]);

                                                                                                                                              const updateRow = (key, field) => (event) => {
                                                                                                                                                  const value = event.target.value;
                                                                                                                                                      setRows((current) =>
                                                                                                                                                            current.map((row) => (row.key === key ? { ...row, [field]: value } : row))
                                                                                                                                                                );
                                                                                                                                                                    if (error) {
                                                                                                                                                                          setError('');
                                                                                                                                                                              }
                                                                                                                                                                                };

                                                                                                                                                                                  const addRow = () => setRows((current) => [...current, emptyRow()]);
                                                                                                                                                                                    const removeRow = (key) =>
                                                                                                                                                                                        setRows((current) => (current.length === 1 ? current : current.filter((row) => row.key !== key)));

                                                                                                                                                                                          const handleSubmit = async (event) => {
                                                                                                                                                                                              event.preventDefault();

                                                                                                                                                                                                  const chosen = rows.filter((row) => row.drugId);
                                                                                                                                                                                                      if (chosen.length === 0) {
                                                                                                                                                                                                            setError('Add at least one drug to the requisition.');
                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                      }

                                                                                                                                                                                                                          const invalid = chosen.find((row) => !(Number(row.requestedQuantity) > 0));
                                                                                                                                                                                                                              if (invalid) {
                                                                                                                                                                                                                                    setError('Every selected drug needs a requested quantity greater than zero.');
                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                  const duplicate = chosen.find(
                                                                                                                                                                                                                                                        (row, index) => chosen.findIndex((other) => other.drugId === row.drugId) !== index
                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                if (duplicate) {
                                                                                                                                                                                                                                                                      setError('Each drug can only appear once. Merge the quantities instead.');
                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                    const payload = {
                                                                                                                                                                                                                                                                                          notes: notes.trim() || null,
                                                                                                                                                                                                                                                                                                items: chosen.map((row) => ({
                                                                                                                                                                                                                                                                                                        drugId: row.drugId,
                                                                                                                                                                                                                                                                                                                requestedQuantity: Number(row.requestedQuantity)
                                                                                                                                                                                                                                                                                                                      }))
                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                              setSaving(true);
                                                                                                                                                                                                                                                                                                                                  setError('');
                                                                                                                                                                                                                                                                                                                                      try {
                                                                                                                                                                                                                                                                                                                                            const result = isEditing
                                                                                                                                                                                                                                                                                                                                                    ? await updateRequisition(requisition.id, payload)
                                                                                                                                                                                                                                                                                                                                                            : await createRequisition(payload);
                                                                                                                                                                                                                                                                                                                                                                  onSaved(result);
                                                                                                                                                                                                                                                                                                                                                                      } catch (submitError) {
                                                                                                                                                                                                                                                                                                                                                                            setError(submitError.message || 'The requisition could not be saved.');
                                                                                                                                                                                                                                                                                                                                                                                } finally {
                                                                                                                                                                                                                                                                                                                                                                                      setSaving(false);
                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                  <Drawer
                                                                                                                                                                                                                                                                                                                                                                                                        open={open}
                                                                                                                                                                                                                                                                                                                                                                                                              onClose={onClose}
                                                                                                                                                                                                                                                                                                                                                                                                                    title={isEditing ? `Edit ${requisition.requisitionNumber}` : 'New requisition'}
                                                                                                                                                                                                                                                                                                                                                                                                                          subtitle={isEditing ? 'Only drafts can be edited' : 'Saved as a draft you can review later'}
                                                                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                                                                    <form onSubmit={handleSubmit} className="space-y-4" noValidate>
                                                                                                                                                                                                                                                                                                                                                                                                                                            {error ? <Alert tone="error">{error}</Alert> : null}

                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="space-y-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                              <h3 className="text-sm font-bold text-primary-900">Drugs requested</h3>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {rows.map((row, index) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div key={row.key} className="rounded-xl border border-sand-200 bg-sand-50/60 p-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="mb-2 flex items-center justify-between">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="text-xs font-semibold uppercase tracking-wide text-primary-500">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Item {index + 1}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {rows.length > 1 ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          type="button"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onClick={() => removeRow(row.key)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  className="inline-flex items-center gap-1 rounded-lg px-1.5 py-1 text-xs font-semibold text-maroon-600 transition hover:bg-maroon-50"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Trash2 className="h-3.5 w-3.5" aria-hidden="true" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Remove
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ) : null}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="grid gap-3 sm:grid-cols-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <label className="field-label" htmlFor={`requisition-drug-${row.key}`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Drug
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <select
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        id={`requisition-drug-${row.key}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            value={row.drugId}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onChange={updateRow(row.key, 'drugId')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    className="field"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <option value="">Select a drug</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {drugs.map((drug) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <option key={drug.id} value={drug.id}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {drug.name} ({drug.code})
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          label="Quantity needed"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            name={`requisition-quantity-${row.key}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              type="number"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                min="0"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  step="any"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    value={row.requestedQuantity}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onChange={updateRow(row.key, 'requestedQuantity')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        placeholder="0"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ))}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Button type="button" variant="outline" size="sm" onClick={addRow}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Plus className="h-4 w-4" aria-hidden="true" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Add another drug
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <label className="field-label" htmlFor="requisition-notes">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Notes
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <textarea
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              id="requisition-notes"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          value={notes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onChange={(event) => setNotes(event.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  rows={3}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              placeholder="Optional context for the reviewer"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          className="field resize-none"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="flex flex-col gap-2 border-t border-sand-200 pt-4 sm:flex-row-reverse">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Button type="submit" loading={saving} className="sm:flex-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <ClipboardList className="h-4 w-4" aria-hidden="true" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {saving ? 'Saving' : isEditing ? 'Save changes' : 'Create draft'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Button type="button" variant="outline" onClick={onClose} className="sm:flex-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Cancel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </Drawer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }